(1, 19, 3, '<p><strong>MENSAJE DE PRUEBA </strong></p><p><br></p><p>2222</p>', 0, 0, NULL, NULL, 0, 0, NULL, 0, NULL, '2023-12-29 01:51:51', '2023-12-29 01:51:51'),
(2, NULL, NULL, '<p>HOLA ESTE ES UN MENSAJE DE PRUEBA</p>', 0, 0, NULL, NULL, 0, 0, NULL, 0, '2023-12-31 04:03:15', '2023-12-31 04:01:06', '2023-12-31 04:03:15'),
(3, 25, 5, '<p>HFHREJFEF</p><p><br></p>', 0, 0, NULL, NULL, 0, 0, NULL, 0, NULL, '2023-12-31 04:01:16', '2023-12-31 04:01:16'),
